    19	    public static void main(String[] args) {
    20	        Database db = new Database(required("DB_URL"), required("DB_USER"), required("DB_PASSWORD"));
    21	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    22	        System.out.println("Pousada Maré Alta no ar na porta " + build(db).start(port).port());
    23	    }
    24	
    25	    /** Liga as peças. Quem quiser ser avisado dos acontecimentos da pousada entra na lista de inscritos. */
