     1	package pousada.app;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	import java.util.Map;
     6	import java.util.concurrent.ConcurrentHashMap;
     7	import java.util.concurrent.CopyOnWriteArrayList;
     8	import java.util.function.Consumer;
     9	
    10	/** Quem quer saber de algo que aconteceu na pousada se inscreve aqui; quem faz a coisa só publica. */
    11	public class EventBus {
    12	    private final Map<Class<?>, List<Consumer<Object>>> handlers = new ConcurrentHashMap<>();
    13	
    14	    public <E> void subscribe(Class<E> type, Consumer<E> handler) {
    15	        handlers.computeIfAbsent(type, t -> new CopyOnWriteArrayList<>())
    16	                .add(event -> handler.accept(type.cast(event)));
    17	    }
    18	
    19	    /** Um inscrito que falha não impede os outros de serem avisados. */
    20	    public void publish(Object event) {
    21	        for (Consumer<Object> handler : new ArrayList<>(handlers.getOrDefault(event.getClass(), List.of()))) {
    22	            try {
    23	                handler.accept(event);
    24	            } catch (RuntimeException e) {
    25	                System.err.println("Falha ao tratar " + event.getClass().getSimpleName() + ": " + e);
    26	            }
    27	        }
    28	    }
    29	}
