     1	package pousada.app;
     2	
     3	import pousada.domain.*;
     4	import pousada.infra.Database;
     5	import pousada.infra.ReservationRepository;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.YearMonth;
    10	import java.util.List;
    11	
    12	public class ReportService {
    13	    private final Database db;
    14	    private final ReservationRepository repository;
    15	    private final RoomCatalog rooms;
    16	
    17	    public ReportService(Database db, ReservationRepository repository, RoomCatalog rooms) {
    18	        this.db = db;
    19	        this.repository = repository;
    20	        this.rooms = rooms;
    21	    }
    22	
    23	    public String occupancy(LocalDate night) {
    24	        List<Reservation> occupying = db.inTransaction(c -> repository.findPaidOccupying(c, night));
    25	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    26	        for (Reservation r : occupying) {
    27	            row(csv, r.room().number(), r.room().type(), r.id(), r.checkIn(), r.checkOut());
    28	        }
    29	        return row(csv, "total", occupying.size() + "/" + rooms.size()).toString();
    30	    }
    31	
    32	    public String revenue(YearMonth month) {
    33	        List<Reservation> starting = db.inTransaction(c ->
    34	                repository.findCheckingInBetween(c, month.atDay(1), month.plusMonths(1).atDay(1)));
    35	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    36	        BigDecimal total = Money.ZERO;
    37	        for (Reservation r : starting) {
    38	            if (r.retained().signum() > 0) {
    39	                row(csv, r.id(), r.room().number(), r.checkIn(), r.checkOut(), r.status(), r.retained());
    40	                total = total.add(r.retained());
    41	            }
    42	        }
    43	        return row(csv, "total", total).toString();
    44	    }
    45	
    46	    private static StringBuilder row(StringBuilder csv, Object... cells) {
    47	        for (int i = 0; i < cells.length; i++) {
    48	            csv.append(i == 0 ? "" : ",").append(cells[i] instanceof BigDecimal b ? b.toPlainString() : cells[i]);
    49	        }
    50	        return csv.append('\n');
    51	    }
    52	}
