     1	package pousada.notification;
     2	
     3	import pousada.app.*;
     4	import pousada.domain.Formats;
     5	import pousada.domain.Reservation;
     6	
     7	public class FinanceNotifier implements EventSubscriber {
     8	    static final String ADDRESS = "financeiro@pousadamarealta.com.br";
     9	
    10	    private final MessageSender sender;
    11	
    12	    public FinanceNotifier(MessageSender sender) {
    13	        this.sender = sender;
    14	    }
    15	
    16	    @Override
    17	    public void subscribeTo(EventBus bus) {
    18	        bus.subscribe(ReservationConfirmed.class, e -> onConfirmed(e.reservation()));
    19	        bus.subscribe(ConfirmedReservationCancelled.class, e -> onCancelled(e.reservation()));
    20	    }
    21	
    22	    private void onConfirmed(Reservation r) {
    23	        sender.send(Message.Channel.EMAIL, ADDRESS, "Pagamento recebido - reserva " + r.id(),
    24	                "Recebemos o pagamento da reserva nº " + r.id() + ": " + Formats.money(r.amountPaid()) + ".");
    25	    }
    26	
    27	    private void onCancelled(Reservation r) {
    28	        if (r.refund().signum() == 0) {
    29	            return;
    30	        }
    31	        sender.send(Message.Channel.EMAIL, ADDRESS, "Reembolso - reserva " + r.id(),
    32	                "A reserva nº " + r.id() + " foi cancelada. Valor a devolver: " + Formats.money(r.refund()) + ".");
    33	    }
    34	}
