    10	public class ReservationService {
    11	    private final Database db;
    12	    private final ReservationRepository repository;
    13	    private final RoomCatalog rooms;
    14	    private final EventBus events;
    15	
    16	    public ReservationService(Database db, ReservationRepository repository, RoomCatalog rooms, EventBus events) {
    17	        this.db = db;
    18	        this.repository = repository;
    19	        this.rooms = rooms;
    20	        this.events = events;
    21	    }
    22	
    23	    public Reservation create(NewReservation request) {
    24	        Room room = rooms.find(request.roomNumber()).orElseThrow(() ->
    25	                new DomainException(DomainException.Code.ROOM_NOT_FOUND, "Quarto " + request.roomNumber() + " não existe"));
    26	        Reservation reservation = Reservation.open(room, request.guest(), request.checkIn(), request.checkOut(),
    27	                request.guests(), request.ratePlan());
    28	        return db.inTransaction(c -> {
    29	            repository.lockRoom(c, room);
    30	            if (repository.existsOverlapping(c, room, request.checkIn(), request.checkOut())) {
    31	                throw new DomainException(DomainException.Code.ROOM_UNAVAILABLE,
    32	                        "Quarto " + room.number() + " já reservado em alguma das noites pedidas");
    33	            }
    34	            return repository.insert(c, reservation);
    35	        });
    36	    }
    37	
    38	    public Reservation get(long id) {
    39	        return db.inTransaction(c -> repository.find(c, id, false).orElseThrow(() -> notFound(id)));
    40	    }
    41	
    42	    public Reservation confirm(long id) {
    43	        Reservation reservation = change(id, Reservation::confirm);
    44	        events.publish(new ReservationConfirmed(reservation));
    45	        return reservation;
    46	    }
    47	
    48	    public Reservation cancel(long id) {
    49	        AtomicReference<ReservationStatus> before = new AtomicReference<>();
    50	        Reservation reservation = change(id, r -> {
    51	            before.set(r.status());
    52	            r.cancel();
    53	        });
    54	        if (before.get() == ReservationStatus.CONFIRMED) {
    55	            events.publish(new ConfirmedReservationCancelled(reservation));
    56	        }
    57	        return reservation;
    58	    }
    59	
    60	    public Reservation checkIn(long id) {
    61	        return change(id, Reservation::startStay);
    62	    }
    63	
    64	    public Document checkOut(long id) {
    65	        return Document.of(change(id, Reservation::endStay));
    66	    }
    67	
    68	    public Document document(long id) {
    69	        return Document.of(get(id));
    70	    }
    71	
    72	    private Reservation change(long id, Consumer<Reservation> operation) {
    73	        return db.inTransaction(c -> {
    74	            Reservation reservation = repository.find(c, id, true).orElseThrow(() -> notFound(id));
    75	            operation.accept(reservation);
    76	            repository.save(c, reservation);
    77	            return reservation;
    78	        });
    79	    }
    80	
    81	    private static DomainException notFound(long id) {
    82	        return new DomainException(DomainException.Code.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
    83	    }
    84	}
