    19	    @Override
    20	    public void send(Message.Channel channel, String to, String subject, String body) {
    21	        db.inTransaction(c -> {
    22	            try (PreparedStatement ps = c.prepareStatement(
    23	                    "INSERT INTO messages (channel, recipient, subject, body) VALUES (?,?,?,?)")) {
    24	                ps.setString(1, channel.name());
    25	                ps.setString(2, to);
    26	                ps.setString(3, subject);
    27	                ps.setString(4, body);
    28	                ps.executeUpdate();
    29	            }
    30	            return null;
    31	        });
