    36	            List<Message> result = new ArrayList<>();
    37	            try (PreparedStatement ps = c.prepareStatement(
    38	                    "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
    39	                 ResultSet rs = ps.executeQuery()) {
    40	                while (rs.next()) {
    41	                    result.add(new Message(rs.getLong("id"), Message.Channel.valueOf(rs.getString("channel")),
    42	                            rs.getString("recipient"), rs.getString("subject"), rs.getString("body")));
