    10	
    11	public class ReservationRepository {
    12	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    13	            + "guests, rate_plan, subtotal, discount, total, status, amount_paid, refund";
    14	
    15	    private final RoomCatalog rooms;
    16	
    17	    public ReservationRepository(RoomCatalog rooms) {
    18	        this.rooms = rooms;
    19	    }
    20	
    21	    /** Serializa quem mexe nas reservas do mesmo quarto até o fim da transação. */
    22	    public void lockRoom(Connection c, Room room) throws SQLException {
    23	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    24	            ps.setLong(1, room.number());
    25	            ps.execute();
    26	        }
    27	    }
    28	
    29	    public boolean existsOverlapping(Connection c, Room room, LocalDate checkIn, LocalDate checkOut) throws SQLException {
    30	        String sql = "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    31	                + "AND check_in < ? AND check_out > ? LIMIT 1";
    32	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    33	            ps.setInt(1, room.number());
    34	            ps.setObject(2, checkOut);
    35	            ps.setObject(3, checkIn);
    36	            try (ResultSet rs = ps.executeQuery()) {
    37	                return rs.next();
    38	            }
    39	        }
    40	    }
    41	
    42	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    43	        String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    44	                + "guests, rate_plan, subtotal, discount, total, status, amount_paid, refund) "
    45	                + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id";
    46	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    47	            ps.setInt(1, r.room().number());
    48	            ps.setString(2, r.guest().name());
    49	            ps.setString(3, r.guest().email());
    50	            ps.setString(4, r.guest().cpf());
    51	            ps.setObject(5, r.checkIn());
    52	            ps.setObject(6, r.checkOut());
    53	            ps.setInt(7, r.guests());
    54	            ps.setString(8, r.ratePlan().name());
    55	            ps.setBigDecimal(9, r.quote().subtotal());
    56	            ps.setBigDecimal(10, r.quote().discount());
    57	            ps.setBigDecimal(11, r.quote().total());
    58	            ps.setString(12, r.status().name());
    59	            ps.setBigDecimal(13, r.amountPaid());
    60	            ps.setBigDecimal(14, r.refund());
    61	            try (ResultSet rs = ps.executeQuery()) {
    62	                rs.next();
    63	                return r.withId(rs.getLong(1));
    64	            }
    65	        }
    66	    }
    67	
    68	    public Optional<Reservation> find(Connection c, long id, boolean forUpdate) throws SQLException {
    69	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + (forUpdate ? " FOR UPDATE" : "");
    70	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    71	            ps.setLong(1, id);
    72	            try (ResultSet rs = ps.executeQuery()) {
    73	                return rs.next() ? Optional.of(read(rs)) : Optional.empty();
    74	            }
    75	        }
    76	    }
    77	
    78	    public void save(Connection c, Reservation r) throws SQLException {
    79	        try (PreparedStatement ps = c.prepareStatement(
    80	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    81	            ps.setString(1, r.status().name());
    82	            ps.setBigDecimal(2, r.amountPaid());
    83	            ps.setBigDecimal(3, r.refund());
    84	            ps.setLong(4, r.id());
    85	            ps.executeUpdate();
    86	        }
    87	    }
    88	
    89	    /** Reservas pagas que ocupam um quarto na noite indicada, por número do quarto. */
    90	    public List<Reservation> findPaidOccupying(Connection c, LocalDate night) throws SQLException {
    91	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE status = ANY (?) "
    92	                + "AND check_in <= ? AND check_out > ? ORDER BY room_number, id";
    93	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    94	            ps.setArray(1, c.createArrayOf("varchar",
    95	                    ReservationStatus.paidOnes().stream().map(Enum::name).toArray()));
    96	            ps.setObject(2, night);
    97	            ps.setObject(3, night);
    98	            return readAll(ps);
    99	        }
   100	    }
   101	
   102	    /** Reservas com entrada em [from, to), por data de entrada e número. */
   103	    public List<Reservation> findCheckingInBetween(Connection c, LocalDate from, LocalDate to) throws SQLException {
   104	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
   105	                + "ORDER BY check_in, id";
   106	        try (PreparedStatement ps = c.prepareStatement(sql)) {
   107	            ps.setObject(1, from);
   108	            ps.setObject(2, to);
   109	            return readAll(ps);
   110	        }
   111	    }
   112	
   113	    private List<Reservation> readAll(PreparedStatement ps) throws SQLException {
   114	        List<Reservation> result = new ArrayList<>();
   115	        try (ResultSet rs = ps.executeQuery()) {
   116	            while (rs.next()) {
   117	                result.add(read(rs));
   118	            }
   119	        }
   120	        return result;
   121	    }
   122	
   123	    private Reservation read(ResultSet rs) throws SQLException {
   124	        LocalDate checkIn = rs.getObject("check_in", LocalDate.class);
   125	        LocalDate checkOut = rs.getObject("check_out", LocalDate.class);
   126	        Quote quote = new Quote(Quote.nightsBetween(checkIn, checkOut), rs.getBigDecimal("subtotal"),
   127	                rs.getBigDecimal("discount"), rs.getBigDecimal("total"));
   128	        return new Reservation(rs.getLong("id"),
   129	                rooms.find(rs.getInt("room_number")).orElseThrow(),
   130	                new Guest(rs.getString("guest_name"), rs.getString("guest_email"), rs.getString("guest_cpf")),
   131	                checkIn, checkOut, rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), quote,
   132	                ReservationStatus.valueOf(rs.getString("status")),
   133	                rs.getBigDecimal("amount_paid"), rs.getBigDecimal("refund"));
   134	    }
   135	}
