    10	public class Database implements AutoCloseable {
    11	    @FunctionalInterface
    12	    public interface Work<T> {
    13	        T run(Connection connection) throws SQLException;
    14	    }
    15	
    16	    private static final String SCHEMA = """
    17	            CREATE TABLE IF NOT EXISTS reservations (
    18	                id BIGSERIAL PRIMARY KEY,
    19	                room_number INT NOT NULL,
    20	                guest_name TEXT NOT NULL,
    21	                guest_email TEXT NOT NULL,
    22	                guest_cpf TEXT NOT NULL,
    23	                check_in DATE NOT NULL,
    24	                check_out DATE NOT NULL,
    25	                guests INT NOT NULL,
    26	                rate_plan VARCHAR(20) NOT NULL,
    27	                subtotal NUMERIC(12,2) NOT NULL,
    28	                discount NUMERIC(12,2) NOT NULL,
    29	                total NUMERIC(12,2) NOT NULL,
    30	                status VARCHAR(20) NOT NULL,
    31	                amount_paid NUMERIC(12,2) NOT NULL,
    32	                refund NUMERIC(12,2)
    33	            );
    34	            CREATE INDEX IF NOT EXISTS reservations_room_dates ON reservations (room_number, check_in, check_out);
    35	            CREATE INDEX IF NOT EXISTS reservations_check_in ON reservations (check_in);
    36	            CREATE TABLE IF NOT EXISTS messages (
    37	                id BIGSERIAL PRIMARY KEY,
    38	                channel VARCHAR(20) NOT NULL,
    39	                recipient TEXT NOT NULL,
    40	                subject TEXT NOT NULL,
    41	                body TEXT NOT NULL
    42	            );
    43	            """;
    44	
    45	    private final HikariDataSource dataSource;
    46	
    47	    public Database(String url, String user, String password) {
    48	        HikariConfig config = new HikariConfig();
    49	        config.setJdbcUrl(url);
    50	        config.setUsername(user);
    51	        config.setPassword(password);
    52	        config.setMaximumPoolSize(10);
    53	        config.setInitializationFailTimeout(60_000);
    54	        this.dataSource = new HikariDataSource(config);
    55	        createSchema();
    56	    }
    57	
    58	    private void createSchema() {
    59	        inTransaction(c -> {
    60	            try (Statement s = c.createStatement()) {
    61	                // evita corrida entre instâncias subindo juntas
    62	                s.execute("SELECT pg_advisory_xact_lock(-1)");
    63	                s.execute(SCHEMA);
    64	            }
    65	            return null;
    66	        });
    67	    }
    68	
    69	    public <T> T inTransaction(Work<T> work) {
    70	        try (Connection c = dataSource.getConnection()) {
    71	            c.setAutoCommit(false);
    72	            try {
    73	                T result = work.run(c);
    74	                c.commit();
    75	                return result;
    76	            } catch (Throwable t) {
    77	                c.rollback();
    78	                throw t;
    79	            }
    80	        } catch (SQLException e) {
    81	            throw new PersistenceException(e);
    82	        }
    83	    }
    84	
    85	    @Override
    86	    public void close() {
    87	        dataSource.close();
    88	    }
