    22	    public Reservation(long id, Room room, Guest guest, LocalDate checkIn, LocalDate checkOut, int guests,
    23	                       RatePlan ratePlan, Quote quote, ReservationStatus status,
    24	                       BigDecimal amountPaid, BigDecimal refund) {
    25	        this.id = id;
    26	        this.room = room;
    27	        this.guest = guest;
    28	        this.checkIn = checkIn;
    29	        this.checkOut = checkOut;
    30	        this.guests = guests;
