    34	        this.amountPaid = amountPaid;
    35	        this.refund = refund;
    36	    }
    37	
    38	    /** Reserva nova, pendente, ainda sem número. */
    39	    public static Reservation open(Room room, Guest guest, LocalDate checkIn, LocalDate checkOut,
    40	                                   int guests, RatePlan ratePlan) {
    41	        if (guests > room.capacity()) {
    42	            throw new DomainException(DomainException.Code.CAPACITY_EXCEEDED,
    43	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    44	        }
    45	        return new Reservation(0, room, guest, checkIn, checkOut, guests, ratePlan,
    46	                Quote.of(room, checkIn, checkOut, ratePlan), PENDING, Money.ZERO, null);
    47	    }
    48	
    49	    public Reservation withId(long newId) {
    50	        return new Reservation(newId, room, guest, checkIn, checkOut, guests, ratePlan, quote,
    51	                status, amountPaid, refund);
    52	    }
    53	
    54	    public void confirm() {
    55	        moveTo(CONFIRMED, PENDING);
    56	        amountPaid = quote.total();
    57	    }
    58	
    59	    public void startStay() {
    60	        moveTo(CHECKED_IN, CONFIRMED);
    61	    }
    62	
    63	    public void endStay() {
    64	        moveTo(CHECKED_OUT, CHECKED_IN);
    65	    }
    66	
    67	    public void cancel() {
    68	        moveTo(CANCELLED, PENDING, CONFIRMED);
    69	        refund = ratePlan.refundOf(amountPaid);
    70	    }
    71	
    72	    /** O que ficou com a pousada: o que foi pago menos o que foi devolvido. */
    73	    public BigDecimal retained() {
    74	        return refund == null ? amountPaid : Money.round(amountPaid.subtract(refund));
    75	    }
    76	
    77	    private void moveTo(ReservationStatus target, ReservationStatus... allowedFrom) {
    78	        if (!Arrays.asList(allowedFrom).contains(status)) {
    79	            throw new DomainException(DomainException.Code.OPERATION_NOT_ALLOWED,
    80	                    "Reserva " + id + " está " + status + " e não pode ir para " + target);
    81	        }
    82	        status = target;
    83	    }
