    54	    public void confirm() {
    55	        moveTo(CONFIRMED, PENDING);
    56	        amountPaid = quote.total();
    57	    }
    58	
    59	    public void startStay() {
    60	        moveTo(CHECKED_IN, CONFIRMED);
    61	    }
    62	
    63	    public void endStay() {
    64	        moveTo(CHECKED_OUT, CHECKED_IN);
    65	    }
    66	
