     1	package pousada.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	/** Alta temporada: de 15/12 ao fim de fevereiro e todo o mês de julho. */
     7	public final class Season {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    private Season() {
    11	    }
    12	
    13	    public static boolean isHigh(LocalDate night) {
    14	        int month = night.getMonthValue();
    15	        return month == 1 || month == 2 || month == 7
    16	                || (month == 12 && night.getDayOfMonth() >= 15);
    17	    }
    18	
    19	    public static BigDecimal nightPrice(BigDecimal nightlyRate, LocalDate night) {
    20	        return isHigh(night) ? Money.round(nightlyRate.multiply(HIGH_SEASON_FACTOR)) : nightlyRate;
    21	    }
    22	}
