168	    private HttpResponse<String> call(String method, String path, String body) throws Exception {
169	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
170	        if (body == null) b.method(method, HttpRequest.BodyPublishers.noBody());
171	        else b.method(method, HttpRequest.BodyPublishers.ofString(body)).header("Content-Type", "application/json");
172	        return http.send(b.build(), HttpResponse.BodyHandlers.ofString());
